def page(records, cursor=None, limit=10):
    if limit < 1:
        raise ValueError('limit')
    ordered = sorted(records, key=lambda x: (x['timestamp'], x['id']))
    if cursor is not None:
        # When filtering by cursor, need to consider both timestamp and id
        # to handle ties properly
        cursor_timestamp, cursor_id = cursor
        ordered = [x for x in ordered if (x['timestamp'] > cursor_timestamp) or 
                   (x['timestamp'] == cursor_timestamp and x['id'] > cursor_id)]
    items = ordered[:limit]
    next_cursor = None
    if len(ordered) > limit:
        # The next cursor should be the timestamp and id of the last item in this page
        next_cursor = (items[-1]['timestamp'], items[-1]['id'])
    return {'items': items, 'next_cursor': next_cursor}
